// mpv_client_api_version() has no inputs and is safe at any time.
// Just call it to exercise the code path. No outputs to persist.
unsigned long ver = mpv_client_api_version();
// Basic sanity property: version should be non-zero in released builds.
FUZZ_ASSERT(ver != 0, "mpv_client_api_version returned 0");

// Create a new (pre-initialized) mpv instance. May return NULL (OOM or bad LC_NUMERIC).
mpv_handle *ctx = mpv_create();
if (!ctx) { FUZZ_BAIL(); }
// Track initialization state for downstream stubs.
FUZZ_SET_ATTR_INT(ctx, "initialized", 0);
FUZZ_SET_ATTR_INT(ctx, "weak", 0);
// Provide ctx as persistent output.

// Terminate the player and destroy the handle, potentially blocking until shutdown.
mpv_terminate_destroy(ctx);
// Drop ctx; it is invalid after this call.
